  align-items: center;
}

.editorial-image {
  background: #eee;
  aspect-ratio: 16/9;
  border-radius: 12px;
}

footer {
  background: var(--primary);
  color: white;
  padding: 4rem 5%;
  text-align: center;
}

.footer-links {
  display: flex;
  justify-content: center;
  gap: 2rem;
  margin-bottom: 2rem;
